const env = typeof $env === 'object' && $env ? $env : {};
const graphApiVersion = String(env.GRAPH_API_VERSION || 'v25.0').trim();
const accessToken = String(env.INSTAGRAM_GRAPH_API_TOKEN || '').trim();
const checkedAt = new Date().toISOString();
const requiredScopes = ['instagram_basic', 'instagram_content_publish', 'pages_show_list'];
const recommendedScopes = ['pages_read_engagement', 'instagram_manage_insights'];
if (!accessToken) {
  return [{
    json: {
      workflow_name: 'wf_instagram_publish_readiness',
      run_status: 'failed',
      error_message: 'INSTAGRAM_GRAPH_API_TOKEN is empty in the running n8n container env. Restart n8n after updating .env.',
      details_json: {
        checked_at: checkedAt,
        graph_api_version: graphApiVersion,
        missing_token: true,
        required_scopes: requiredScopes,
        recommended_scopes: recommendedScopes
      }
    }
  }];
}
const fetchJson = async (path) => {
  try {
    const response = await helpers.httpRequest({
      method: 'GET',
      url: `https://graph.facebook.com/${graphApiVersion}/${path}`,
      qs: { access_token: accessToken },
      json: true,
      returnFullResponse: true,
      ignoreHttpStatusErrors: true
    });
    const statusCode = Number(response.statusCode ?? 0);
    const body = response.body ?? {};
    return {
      ok: statusCode >= 200 && statusCode < 300 && !body.error,
      status: statusCode,
      body
    };
  } catch (error) {
    return {
      ok: false,
      status: Number(error?.statusCode ?? 0),
      body: error?.response?.body ?? {
        error: {
          message: error.message
        }
      }
    };
  }
};
const me = await fetchJson('me?fields=id,name');
const permissions = await fetchJson('me/permissions');
const pages = await fetchJson('me/accounts?fields=id,name');
const grantedScopes = permissions.ok
  ? (permissions.body.data ?? [])
      .filter((item) => item.status === 'granted')
      .map((item) => item.permission)
  : [];
const nonGrantedScopes = permissions.ok
  ? (permissions.body.data ?? [])
      .filter((item) => item.status !== 'granted')
      .map((item) => ({ permission: item.permission, status: item.status }))
  : [];
const missingRequiredScopes = requiredScopes.filter((scope) => !grantedScopes.includes(scope));
const missingRecommendedScopes = recommendedScopes.filter((scope) => !grantedScopes.includes(scope));
const linkedPages = pages.ok
  ? (pages.body.data ?? []).map((page) => ({ id: page.id, name: page.name }))
  : [];
const errors = [];
if (!me.ok) {
  errors.push(`/me failed: ${me.body.error?.message ?? 'unknown error'}`);
}
if (!permissions.ok) {
  errors.push(`/me/permissions failed: ${permissions.body.error?.message ?? 'unknown error'}`);
}
if (!pages.ok) {
  errors.push(`/me/accounts failed: ${pages.body.error?.message ?? 'unknown error'}`);
}
if (missingRequiredScopes.length) {
  errors.push(`Missing required scopes: ${missingRequiredScopes.join(', ')}`);
}
if (!linkedPages.length) {
  errors.push('No linked Facebook Pages were returned by /me/accounts.');
}
return [{
  json: {
    workflow_name: 'wf_instagram_publish_readiness',
    run_status: errors.length ? 'failed' : 'success',
    error_message: errors.join(' | '),
    details_json: {
      checked_at: checkedAt,
      graph_api_version: graphApiVersion,
      token_present: true,
      me_status: me.status,
      permissions_status: permissions.status,
      pages_status: pages.status,
      me: me.body,
      granted_scopes: grantedScopes,
      non_granted_scopes: nonGrantedScopes,
      missing_required_scopes: missingRequiredScopes,
      missing_recommended_scopes: missingRecommendedScopes,
      linked_pages: linkedPages,
      linked_pages_count: linkedPages.length
    }
  }
}];

return [{
  json: {
    ...$json,
    workflow_name_sql: String($json.workflow_name ?? 'wf_instagram_publish_readiness').replaceAll("'", "''"),
    run_status_sql: String($json.run_status ?? 'failed').replaceAll("'", "''"),
    error_message_sql: String($json.error_message ?? '').replaceAll("'", "''"),
    details_json_sql: JSON.stringify($json.details_json ?? {}).replaceAll("'", "''")
  }
}];
